import { expect } from '@esm-bundle/chai';
// NO static import of the component: <td-tree-select> is defined LATE (dynamic import below), after the no-JS checks.

// v0.29.0 (plan v0.29.0-tree M8 / M9, ADR 0012) — PHP td_tree_select() markup (test/ssr/fixtures/tree-select.html,
// GENERATED by `node test/ssr/build-tree-select-fixture.mjs` from test/ssr/tree-select.fixtures.json; kept fresh by
// test/php/td-ssr-tree-select.test.js) in Chromium, Firefox AND WebKit:
//   - without JS every form submits exactly what the fixture says (locked values exactly once, a disabled control
//     nothing) and form.checkValidity() is as expected;
//   - element mode (tree-select@1): the host box is the same before and after the upgrade (± 1 px) for single AND
//     multiple; the upgraded state (value, text, locks) matches; FormData + validity are unchanged by the upgrade;
//   - drifted markup (marker without a select / with stray children) renders safely.
// DOM nodes are compared as booleans (`a === b`): a failing chai assertion carrying DOM nodes hangs the runner.
const link = document.createElement('link');
link.rel = 'stylesheet';
link.href = '/td.css';
document.head.appendChild(link);
await new Promise((r) => { link.onload = r; link.onerror = r; });
document.addEventListener('submit', (e) => e.preventDefault(), true);

const SPEC = await (await fetch('/test/ssr/tree-select.fixtures.json')).json();
const FIXTURE = await (await fetch('/test/ssr/fixtures/tree-select.html')).text();
const root = document.createElement('div');
root.innerHTML = FIXTURE;
document.body.appendChild(root);
const caseForm = (id) => root.querySelector(`form[data-case="${id}"]`);
const caseHost = (id) => caseForm(id).querySelector('td-tree-select');
const entries = (form) => [...new FormData(form)];
const box = (el) => {
  const r = el.getBoundingClientRect();
  return { x: r.x, y: r.y, w: r.width, h: r.height };
};

// drifted markup: the marker without a select, and with a stray element
const drift = document.createElement('form');
drift.innerHTML = '<td-tree-select data-td-ssr="tree-select@1" id="drift-a" name="d"></td-tree-select>'
  + '<td-tree-select data-td-ssr="tree-select@1" id="drift-b" name="e"><div class="x">rác</div><select class="td-tree-select__native" name="e">'
  + '<option value="v" selected>&lt;img src=x onerror=alert(1)&gt;</option></select></td-tree-select>';
document.body.appendChild(drift);

// ---------------------------------------------------------------- before define --------------------------------------
const before = {};
for (const c of [...SPEC.cases, ...SPEC.nativeCases]) {
  const form = caseForm(c.id);
  before[c.id] = { submit: entries(form), valid: form.checkValidity(), box: box(form.querySelector('td-tree-select')) };
}
const shellHeight = getComputedStyle(caseHost('m-basic').querySelector('select')).height;
const nativeMultiRows = caseForm('n-multi').querySelector('select').size;

await import('./td-tree-select.js');
await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));

describe('td_tree_select — no JS (native <select>)', () => {
  it('every form submits the expected entries (locked values once, disabled control nothing) + validity', () => {
    for (const c of SPEC.cases) {
      expect(before[c.id].submit, c.id).to.deep.equal(c.submit);
      expect(before[c.id].valid, `${c.id} valid`).to.equal(c.valid);
    }
    for (const c of SPEC.nativeCases) expect(before[c.id].submit, c.id).to.deep.equal(c.submit);
  });

  it('element mode: even the multiple select is one control high; native mode keeps its rows', () => {
    expect(parseFloat(shellHeight)).to.be.within(30, 50);
    expect(nativeMultiRows).to.equal(8);
  });
});

describe('td-tree-select — upgrade of the PHP markup (tree-select@1)', () => {
  it('the host box does not move (± 1 px) — single and multiple', () => {
    for (const c of SPEC.cases.filter((x) => x.box)) {
      const after = box(caseHost(c.id));
      const b = before[c.id].box;
      for (const k of ['x', 'y', 'w', 'h']) expect(Math.abs(after[k] - b[k]), `${c.id} ${k}: ${b[k]} → ${after[k]}`).to.be.at.most(1);
    }
  });

  it('upgraded: marker gone, select + hidden inputs gone, value / text / locks as expected', () => {
    for (const c of SPEC.cases) {
      const h = caseHost(c.id);
      expect(h.hasAttribute('data-td-ssr'), c.id).to.equal(false);
      expect(h.querySelector('select, input[type="hidden"]'), c.id).to.equal(null);
      expect(h.value, c.id).to.deep.equal(c.expect.value);
      if (c.expect.text) {
        const input = h.querySelector('.td-tree-select__input');
        const text = input ? input.value : h.querySelector('.td-tree-select__value').textContent;
        expect(text, c.id).to.equal(c.expect.text);
      }
      if (c.expect.required) expect(h.hasAttribute('required'), c.id).to.equal(true);
      if (c.expect.disabled) expect(h.hasAttribute('disabled'), c.id).to.equal(true);
      if ('allowClear' in c.expect) expect(h.hasAttribute('allow-clear'), c.id).to.equal(c.expect.allowClear);
      if (c.expect.locked) {
        for (const v of c.expect.locked) expect(h._model.node(v).locked, `${c.id} ${v}`).to.equal(true);
      }
      if (c.expect.singleLocked) expect(h._model.singleLocked(), c.id).to.equal(true);
    }
  });

  it('FormData and validity are the same before and after the upgrade', () => {
    for (const c of [...SPEC.cases, ...SPEC.nativeCases]) {
      const form = caseForm(c.id);
      expect(entries(form), c.id).to.deep.equal(c.submitAfter ?? before[c.id].submit);
      if ('valid' in c) expect(form.checkValidity(), `${c.id} valid`).to.equal(c.valid);
    }
  });

  it('a single locked selection stays locked: no other pick, no clear', () => {
    const h = caseHost('s-locked');
    const input = h.querySelector('[role="combobox"]');
    input.focus();
    input.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', bubbles: true, cancelable: true }));
    const li = [...h._menuElement.querySelectorAll('[role="treeitem"]')].find((x) => x.textContent.startsWith('Laptop'));
    li.querySelector('.td-tree__label').click();
    expect(h.value).to.equal('apple');
    expect(h.querySelector('.td-tree-select__clear')).to.equal(null);
    input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true, cancelable: true }));
    expect(entries(caseForm('s-locked'))).to.deep.equal([['owner', 'apple']]);
  });

  it('drifted markup renders safely (text only, no crash)', () => {
    const a = drift.querySelector('#drift-a');
    const b = drift.querySelector('#drift-b');
    expect(!!a.querySelector('.td-tree-select__control')).to.equal(true);
    expect(a.value).to.equal('');
    expect(!!b.querySelector('.td-tree-select__control')).to.equal(true);
    expect(b.querySelector('.x')).to.equal(null);
    expect(b.querySelector('img')).to.equal(null);
    expect(b.value).to.equal('v');
    expect(entries(drift)).to.deep.equal([['e', 'v']]);
  });
});
